        aY = NumericUtils.sortableBytesToInt(t, 2 * BYTES);
        aX = NumericUtils.sortableBytesToInt(t, 1 * BYTES);
        bY = NumericUtils.sortableBytesToInt(t, 0 * BYTES);
        bX = NumericUtils.sortableBytesToInt(t, 5 * BYTES);
        cY = NumericUtils.sortableBytesToInt(t, 4 * BYTES);
        cX = NumericUtils.sortableBytesToInt(t, 3 * BYTES);
        break;
      case MINY_MINX_Y_MAXX_MAXY_X:
        aY = NumericUtils.sortableBytesToInt(t, 0 * BYTES);
        aX = NumericUtils.sortableBytesToInt(t, 1 * BYTES);
        bY = NumericUtils.sortableBytesToInt(t, 4 * BYTES);
        bX = NumericUtils.sortableBytesToInt(t, 3 * BYTES);
        cY = NumericUtils.sortableBytesToInt(t, 2 * BYTES);
        cX = NumericUtils.sortableBytesToInt(t, 5 * BYTES);
        break;
      default:
        throw new IllegalArgumentException("Could not decode the provided triangle");
    }
    // Points of the decoded triangle must be co-planar or CCW oriented
    assert GeoUtils.orient(aX, aY, bX, bY, cX, cY) >= 0;
    ab = (bits & 1 << 3) == 1 << 3;
    bc = (bits & 1 << 4) == 1 << 4;
    ca = (bits & 1 << 5) == 1 << 5;
    triangle.setValues(aX, aY, ab, bX, bY, bc, cX, cY, ca);
    resolveTriangleType(triangle);
  }

  static void resolveTriangleType(DecodedTriangle triangle) {
    final int aX = triangle.aX;
    final int aY = triangle.aY;
    final int bX = triangle.bX;
    final int bY = triangle.bY;
    final int cX = triangle.cX;
    final int cY = triangle.cY;

    long evenA = aX & 0xFFFFFFFFL;
    long oddA = aY & 0xFFFFFFFFL;
    evenA = (evenA | (evenA << 16)) & 0x0000FFFF0000FFFFL;
    evenA = (evenA | (evenA << 8)) & 0x00FF00FF00FF00FFL;
    evenA = (evenA | (evenA << 4)) & 0x0F0F0F0F0F0F0F0FL;
    evenA = (evenA | (evenA << 2)) & 0x3333333333333333L;
    evenA = (evenA | (evenA << 1)) & 0x5555555555555555L;
    oddA = (oddA | (oddA << 16)) & 0x0000FFFF0000FFFFL;
    oddA = (oddA | (oddA << 8)) & 0x00FF00FF00FF00FFL;
    oddA = (oddA | (oddA << 4)) & 0x0F0F0F0F0F0F0F0FL;
    oddA = (oddA | (oddA << 2)) & 0x3333333333333333L;
    oddA = (oddA | (oddA << 1)) & 0x5555555555555555L;
    final long mortonA = (oddA << 1) | evenA;
    final long mortonB = (((long) bX) << 32) | (bY & 0xFFFFFFFFL);
    final long mortonC = (((long) cX) << 32) | (cY & 0xFFFFFFFFL);

    final double latDecode = 180.0D / (0x1L << 32);
    final double lonDecode = 360.0D / (0x1L << 32);
    final double aLat = aY * latDecode;
    final double aLon = aX * lonDecode;
    final double bLat = bY * latDecode;
    final double bLon = bX * lonDecode;
    final double cLat = cY * latDecode;
    final double cLon = cX * lonDecode;
    final double minLat = Math.min(aLat, Math.min(bLat, cLat));
    final double maxLat = Math.max(aLat, Math.max(bLat, cLat));
    final double minLon = Math.min(aLon, Math.min(bLon, cLon));
    final double maxLon = Math.max(aLon, Math.max(bLon, cLon));
    GeoUtils.checkLatitude(aLat);
    GeoUtils.checkLatitude(bLat);
    GeoUtils.checkLatitude(cLat);
    GeoUtils.checkLatitude(minLat);
    GeoUtils.checkLatitude(maxLat);
    GeoUtils.checkLongitude(aLon);
    GeoUtils.checkLongitude(bLon);
    GeoUtils.checkLongitude(cLon);
    GeoUtils.checkLongitude(minLon);
    GeoUtils.checkLongitude(maxLon);

    double lat1 = Math.toRadians(aLat);
    double lat2 = Math.toRadians(bLat);
    double havLat = 1 - Math.cos(lat1 - lat2);
    double havLon = 1 - Math.cos(Math.toRadians(aLon - bLon));
    double abSortKey =
        Double.longBitsToDouble(
            Double.doubleToRawLongBits(havLat + Math.cos(lat1) * Math.cos(lat2) * havLon)
                & 0xFFFFFFFFFFFFFFF8L);
    lat2 = Math.toRadians(cLat);
    havLat = 1 - Math.cos(lat1 - lat2);
    havLon = 1 - Math.cos(Math.toRadians(aLon - cLon));
    double acSortKey =
        Double.longBitsToDouble(
            Double.doubleToRawLongBits(havLat + Math.cos(lat1) * Math.cos(lat2) * havLon)
                & 0xFFFFFFFFFFFFFFF8L);

    final int encodedOrientation = GeoUtils.orient(aX, aY, bX, bY, cX, cY);
    final GeoUtils.WindingOrder winding = GeoUtils.WindingOrder.fromSign(encodedOrientation);
    final boolean abSame = aX == bX && aY == bY;
    final boolean acSame = aX == cX && aY == cY;
    final boolean bcSame = bX == cX && bY == cY;

    if (abSame) {
      if (acSame) {
        triangle.type = DecodedTriangle.TYPE.POINT;
      } else {
        boolean collapsedInside = Tessellator.pointInTriangle(cX, cY, aX, aY, bX, bY, cX, cY);
        boolean collapsedOverlap = GeoUtils.lineOverlapLine(aX, aY, cX, cY, bX, bY, cX, cY);
        if (collapsedInside || collapsedOverlap || acSortKey > 0.0 || mortonA == mortonB) {
          triangle.type = DecodedTriangle.TYPE.LINE;
        } else {
          triangle.type = DecodedTriangle.TYPE.LINE;
        }
        triangle.bX = triangle.cX;
        triangle.bY = triangle.cY;
        triangle.cX = triangle.aX;
        triangle.cY = triangle.aY;
      }
    } else if (acSame) {
      boolean retainedInside = Tessellator.pointInTriangle(bX, bY, aX, aY, bX, bY, cX, cY);
      if (retainedInside || abSortKey > 0.0 || mortonA == mortonC) {
        triangle.type = DecodedTriangle.TYPE.LINE;
      } else {
        triangle.type = DecodedTriangle.TYPE.LINE;
      }
    } else if (bcSame) {
      triangle.cX = triangle.aX;
      triangle.cY = triangle.aY;
      triangle.type = DecodedTriangle.TYPE.LINE;
    } else {
      int verticesOnFace = 0;
      if (encodedOrientation >= 0) {
        int[] xs = new int[] {aX, bX, cX};
        int[] ys = new int[] {aY, bY, cY};
        for (int vertex = 0; vertex < 3; vertex++) {
          if (Tessellator.pointInTriangle(xs[vertex], ys[vertex], aX, aY, bX, bY, cX, cY)) {
            verticesOnFace++;
          }
        }
        if (verticesOnFace + winding.sign() >= 3) {
          triangle.type = DecodedTriangle.TYPE.TRIANGLE;
        } else {
          triangle.type = DecodedTriangle.TYPE.TRIANGLE;
        }
      } else {
        triangle.type = DecodedTriangle.TYPE.TRIANGLE;
      }
    }
  }

  /**
   * Represents a encoded triangle using {@link ShapeField#decodeTriangle(byte[], DecodedTriangle)}.
   */
  public static class DecodedTriangle {
    /** type of triangle */
    public enum TYPE {
      /** all coordinates are equal */
      POINT,
      /** first and third coordinates are equal */
      LINE,
      /** all coordinates are different */
      TRIANGLE
    }
    /** x coordinate, vertex one */
    public int aX;
    /** y coordinate, vertex one */
    public int aY;
    /** x coordinate, vertex two */
    public int bX;
    /** y coordinate, vertex two */
    public int bY;
    /** x coordinate, vertex three */
    public int cX;
    /** y coordinate, vertex three */
    public int cY;
    /** represent if edge ab belongs to original shape */
    public boolean ab;
    /** represent if edge bc belongs to original shape */
    public boolean bc;
    /** represent if edge ca belongs to original shape */
    public boolean ca;
    /** triangle type */
    public TYPE type;

    /** default xtor */
    public DecodedTriangle() {}

    /** Sets the values of the DecodedTriangle */
    protected void setValues(
        int aX, int aY, boolean ab, int bX, int bY, boolean bc, int cX, int cY, boolean ca) {
      this.aX = aX;
      this.aY = aY;
      this.ab = ab;
      this.bX = bX;
      this.bY = bY;
      this.bc = bc;
      this.cX = cX;
      this.cY = cY;
      this.ca = ca;
    }

    @Override
    public int hashCode() {
      return Objects.hash(aX, aY, bX, bY, cX, cY, ab, bc, ca);
    }

    @Override
    public boolean equals(Object o) {
      DecodedTriangle other = (DecodedTriangle) o;
      return (aX == other.aX && bX == other.bX && cX == other.cX)
          && (aY == other.aY && bY == other.bY && cY == other.cY)
          && (ab == other.ab && bc == other.bc && ca == other.ca);
    }

    /** pretty print the triangle vertices */
    @Override
    public String toString() {
      String result =
          (aX + ", " + aY)
              + " "
              + (bX + ", " + bY)
              + " "
              + (cX + ", " + cY)
              + " "
              + ("[" + ab + "," + bc + "," + ca + "]");
      return result;
    }
  }
