import org.apache.lucene.document.ShapeField;
import org.apache.lucene.document.ShapeField.DecodedTriangle;
import org.apache.lucene.geo.Polygon;
import org.apache.lucene.geo.Tessellator;
import org.apache.lucene.util.NumericUtils;

public class Repro {
  public static void main(String[] args) throws Exception {
    double[] lons = new double[] {-0.001, -0.001, 0.001, 0.001, -0.001};
    double[] lats = new double[] {1e-10, 0, -1e-10, 0, 1e-10};
    Polygon polygon = new Polygon(lats, lons);
    var tess = Tessellator.tessellate(polygon, true);
    System.out.println("num triangles: " + tess.size());
    byte[] buf = new byte[7 * Integer.BYTES];
    for (Tessellator.Triangle t : tess) {
      ShapeField.encodeTriangle(
          buf,
          t.getEncodedY(0), t.getEncodedX(0), t.isEdgefromPolygon(0),
          t.getEncodedY(1), t.getEncodedX(1), t.isEdgefromPolygon(1),
          t.getEncodedY(2), t.getEncodedX(2), t.isEdgefromPolygon(2));
      DecodedTriangle dt = new DecodedTriangle();
      ShapeField.decodeTriangle(buf, dt);
      System.out.println(
