import org.apache.lucene.document.ShapeField;
import org.apache.lucene.document.ShapeField.DecodedTriangle;
import org.apache.lucene.geo.Polygon;
import org.apache.lucene.geo.Tessellator;
import org.apache.lucene.geo.Tessellator.Triangle;
import org.apache.lucene.geo.GeoEncodingUtils;

public class Repro3 {
  public static void main(String[] args) throws Exception {
    double[] lons = new double[] {-0.001, -0.001, 0.001, 0.001, -0.001};
    double[] lats = new double[] {1e-10, 0, -1e-10, 0, 1e-10};
    Polygon polygon = new Polygon(lats, lons);
    var tess = Tessellator.tessellate(polygon, true);
    byte[] buf = new byte[7 * Integer.BYTES];
    // query line: lat 0.0 -> 0.001 at lon 0.0
    int qaX = GeoEncodingUtils.encodeLongitude(0.0);
    int qaY = GeoEncodingUtils.encodeLatitude(0.0);
    int qbX = GeoEncodingUtils.encodeLongitude(0.0);
    int qbY = GeoEncodingUtils.encodeLatitude(0.001);
    System.out.println("query line: (" + qaX + "," + qaY + ") -> (" + qbX + "," + qbY + ")");
    for (Triangle t : tess) {
      ShapeField.encodeTriangle(
          buf,
          t.getEncodedY(0), t.getEncodedX(0), t.isEdgefromPolygon(0),
          t.getEncodedY(1), t.getEncodedX(1), t.isEdgefromPolygon(1),
          t.getEncodedY(2), t.getEncodedX(2), t.isEdgefromPolygon(2));
      DecodedTriangle dt = new DecodedTriangle();
      ShapeField.decodeTriangle(buf, dt);
      String rel;
      if (dt.type == DecodedTriangle.TYPE.LINE) {
        rel = "LINE a->b flag(ab)=" + dt.ab;
      } else {
        rel =
            "TRIANGLE crosses-ab:"
                + org.apache.lucene.geo.GeoUtils.lineCrossesLineWithBoundary(
                    dt.aX, dt.aY, dt.bX, dt.bY, qaX, qaY, qbX, qbY)
                + " ab="
                + dt.ab
                + " crosses-bc:"
                + org.apache.lucene.geo.GeoUtils.lineCrossesLineWithBoundary(
                    dt.bX, dt.bY, dt.cX, dt.cY, qaX, qaY, qbX, qbY)
                + " bc="
                + dt.bc
                + " crosses-ca:"
                + org.apache.lucene.geo.GeoUtils.lineCrossesLineWithBoundary(
                    dt.cX, dt.cY, dt.aX, dt.aY, qaX, qaY, qbX, qbY)
                + " ca="
                + dt.ca;
      }
      System.out.println(
          "type="
              + dt.type
              + " ("
              + dt.aX
              + ","
              + dt.aY
              + ")["
              + dt.ab
              + "] ("
              + dt.bX
              + ","
              + dt.bY
              + ")["
              + dt.bc
              + "] ("
              + dt.cX
              + ","
              + dt.cY
              + ")["
              + dt.ca
              + "]  => "
              + rel);
    }
  }
}

